def lookup(key):
 t, _, n = key.partition(":")
 if t == "cons": return CONS.get(n, [])
 if t == "shower": return SHOWERS.get(n, [])
 if t == "star": return STARS.get(n, []) + CONS.get(STAR.get(n, ""), [])
 return []
def count(): return sum(map(len, CONS.values())) + sum(map(len, SHOWERS.values())) + sum(map(len, STARS.values()))
def check():
 return {"constellations": len(CONS), "showers": len(SHOWERS), "short_cons": [k for k, v in CONS.items() if len(v) < 4], "short_showers": [k for k, v in SHOWERS.items() if len(v) < 4]}
